    $tLogBase=['tenant_id'=>$tenant,'sn'=>'T_'.$suffix,'source_sn'=>$source,'change_type'=>'consume','action'=>2,'change_amount'=>1.5,'left_amount'=>100,'remark'=>$private,'extra'=>S::encode(['token'=>$private]),'create_time'=>$now-20,'update_time'=>$now-20];
    $tenantLog=(int)Db::name('tenant_point_log')->insertGetId($tLogBase);
