    $request=['request_id'=>$rid,'tenant_id'=>$tenant,'user_id'=>$user,'key_id'=>321,'kind'=>'tool','app_code'=>'aigc_product_suite','method'=>'POST','path'=>'/api/v1/tools/aigc_product_suite/tasks','tool_task_id'=>(string)$suite,'status'=>'success','billing_status'=>'settled','active'=>0,'consumption_ids'=>S::encode([$consume,$foreignConsume,$otherUserConsume]),'snapshot'=>S::encode(['source_blob'=>$private,'customer_callback'=>['secret_blob'=>$private],'point_events'=>['consume:'.$source=>['user'=>3,'tenant'=>1.5]]]),'payload_hash'=>hash('sha256',$rid),'response_blob'=>$private,'actual_user'=>3,'actual_tenant'=>1.5,'create_time'=>$now-50,'update_time'=>$now-5,'finish_time'=>$now-5];
    $request['id']=(int)S::table('request')->insertGetId($request);
    $wBase=['tenant_id'=>$tenant,'user_id'=>$user,'request_id'=>$rid,'event_id'=>'evt_'.$suffix,'url'=>'https://callback.test/private?token='.$private,'secret_blob'=>$private,'payload_blob'=>$private,'lease_token'=>$private,'last_error'=>$private,'status'=>'delivered','attempts'=>1,'http_code'=>204,'create_time'=>$now-5,'update_time'=>$now-3];
    $webhook=(int)S::table('webhook')->insertGetId($wBase);
