    S::table('webhook')->insert(array_replace($wBase,['user_id'=>$user+1,'event_id'=>'evt_u_'.$suffix]));
    $delivery=(int)S::table('webhook_delivery')->insertGetId(['webhook_id'=>$webhook,'event_id'=>$wBase['event_id'],'attempt'=>1,'http_code'=>204,'error_message'=>$private,'create_time'=>$now-3]);
