    S::table('webhook_delivery')->insert(['webhook_id'=>$webhook,'event_id'=>'evt_wrong_'.$suffix,'attempt'=>3,'http_code'=>500,'create_time'=>$now]);
    $foreignApp=(int)Db::name('ai_app_task')->insertGetId(['tenant_id'=>$tenant+1,'user_id'=>$user,'task_no'=>'AF_'.$suffix,'business_table'=>'aigc_image_task','business_id'=>$foreignImage,'status'=>'success','idempotency_key'=>'IF_'.$suffix,'create_time'=>$now]);
    $foreignAppConsume=(int)Db::name('ai_consumption_log')->insertGetId(array_replace($cBase,['app_task_id'=>$foreignApp,'consume_no'=>'CAF_'.$suffix,'user_point_sn'=>'','tenant_point_sn'=>'']));
    $priced=Trace::build($request,true);check(($priced['consumptions'][0]['price_summary']['retail_unit_points']??null)===3.0&&($priced['consumptions'][0]['price_summary']['sku_key']??'')==='public_4k'&&($priced['consumptions'][0]['price_summary']['frozen_skus'][0]['retail_unit_points']??0)===3.0,'Frozen retail price/SKU summary missing');
    $badApplication=array_replace($request,['request_id'=>$rid.'_app','tool_task_id'=>(string)$foreignImage,'app_code'=>'aigc_image','consumption_ids'=>S::encode([$foreignAppConsume]),'snapshot'=>'{}']);unset($badApplication['id']);
    $badApplication['id']=(int)S::table('request')->insertGetId($badApplication);
