    $empty=array_replace($request,['request_id'=>$rid.'_empty','tool_task_id'=>'','app_code'=>'unregistered_fixture','consumption_ids'=>'[]','snapshot'=>'{}','actual_user'=>0]);unset($empty['id']);
    $empty['id']=(int)S::table('request')->insertGetId($empty);

    $snapshots=[];foreach($tables as $table)$snapshots[$table]=hash('sha256',S::encode(Db::name($table)->order('id','asc')->select()->toArray()));
    $sql=[];Db::listen(function($query)use(&$sql){$sql[]=$query;});
    $platform=Trace::build($request,true);$tenantView=Trace::build($request,false);
    foreach([$platform,$tenantView] as $trace){
        $nodes=array_column($trace['nodes'],null,'id');
        check(count($trace['consumptions'])===1&&$trace['consumptions'][0]['id']==$consume,'Foreign consumption leaked');
        check(isset($nodes['business:aigc_product_suite_task:'.$suite],$nodes['business:aigc_image_task:'.$ownImage],$nodes['app_task:'.$app],$nodes['consumption:'.$consume]),'Explicit business/application/consumption chain missing');
