        check($nodes['app_task:'.$app]['parent_id']==='app_task:'.$parentApp&&$nodes['app_task:'.$parentApp]['parent_id']==='business:aigc_image_task:'.$ownImage&&$nodes['consumption:'.$consume]['parent_id']==='app_task:'.$app,'Task IDs treated as interchangeable');
