        check(count($trace['webhook_deliveries'])===1&&$trace['webhook_deliveries'][0]['id']==$delivery,'Webhook ownership/event binding failed');
        $encoded=S::encode($trace);
        check(!str_contains($encoded,$private)&&!str_contains($encoded,'payload_ciphertext')&&!str_contains($encoded,'price_snapshot')&&!str_contains($encoded,'request_summary')&&!str_contains($encoded,'provider_params_json'),'Private contents exposed');
        check(count($trace['gaps'])>=3,'Missing/foreign/invalid evidence gaps not explicit');
        $times=array_column($trace['timeline'],'time');$sorted=$times;sort($sorted);check($times===$sorted,'Timeline not chronological');
        foreach($trace['nodes'] as $node)check($node['parent_id']===null||isset($nodes[$node['parent_id']]),'Dangling node parent');
    }
    check(count($platform['tenant_point_logs'])===1&&$platform['tenant_point_logs'][0]['id']==$tenantLog,'Platform tenant ledger missing or foreign ledger leaked');
    check($platform['consumptions'][0]['actual_tenant_cost']==1.5&&$platform['consumptions'][0]['upstream_task_id']==='supplier_task_'.$suffix,'Operator monetary/identifier evidence lost');
